import{_ as t,o,c as a,a0 as d}from"./chunks/framework.Bmhw_dvp.js";const k=JSON.parse('{"title":"티켓 직접 발행하기","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://dira.proofer.tech/docs/ticket-writing"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"dira"}],["meta",{"property":"og:locale","content":"ko_KR"}],["meta",{"property":"og:url","content":"https://dira.proofer.tech/docs/ticket-writing"}],["meta",{"property":"og:title","content":"티켓 직접 발행하기"}],["meta",{"property":"og:description","content":"티켓을 큐에 넣으면 cron에 물린 워커가 claude 세션에 넘깁니다. 파일시스템이 곧 큐인 티켓 디스패처."}],["meta",{"property":"og:image","content":"https://dira.proofer.tech/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"name":"twitter:card","content":"summary_large_image"}]]},"headers":[],"relativePath":"docs/ticket-writing.md","filePath":"docs/ticket-writing.md"}'),s={name:"docs/ticket-writing.md"};function i(n,e,c,r,p,l){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="티켓-직접-발행하기" tabindex="-1">티켓 직접 발행하기 <a class="header-anchor" href="#티켓-직접-발행하기" aria-label="Permalink to &quot;티켓 직접 발행하기&quot;">​</a></h1><p><a href="/docs/requirements">요구사항 접수하기</a>는 하고 싶은 말을 그대로 넣고 pm이 쪼개 주기를 기다리는 길입니다. 이 장은 반대쪽입니다. 무엇을 시킬지 이미 알고 있을 때 쓰세요. 버그 하나, 오타 하나, 이미 잘게 갈라져 있는 일에는 해석할 것이 없습니다. 없는 해석을 하자고 pm 세션을 한 번 태울 이유도 없고요. 그럴 때는 티켓을 직접 씁니다.</p><p>밑에서 파일 하나가 만들어지는 것은 똑같습니다. 그 파일을 쓰는 손이 pm 세션이 아니라 폼일 뿐입니다.</p><h2 id="발행-다이얼로그" tabindex="-1">발행 다이얼로그 <a class="header-anchor" href="#발행-다이얼로그" aria-label="Permalink to &quot;발행 다이얼로그&quot;">​</a></h2><p>보드 우상단에 버튼이 둘 있는데, 왼쪽이 <code>티켓 발행</code>입니다(오른쪽 primary는 <code>요구 접수</code>). 보드에서 <code>n</code>을 눌러도 열립니다. 페이지가 아니라 다이얼로그라서 취소가 곧 닫기이고, 뒤에는 보드가 필터·검색·스크롤 그대로 남아 있습니다.</p><p>칸은 다섯입니다.</p><table tabindex="0"><thead><tr><th>칸</th><th>무엇</th></tr></thead><tbody><tr><td><code>title</code></td><td>필수. 한 줄 제목</td></tr><tr><td><code>kind</code></td><td>select — <code>work</code> · <code>request</code> · <code>feedback</code></td></tr><tr><td><code>persona</code></td><td>select — <code>personas/</code> 아래 프로필이 실제로 있는 이름만 뜹니다</td></tr><tr><td><code>deps</code></td><td>기존 티켓 멀티셀렉트. 자유 입력 없음</td></tr><tr><td>본문</td><td><code>## Goal</code> · <code>## Done when</code> 골격이 미리 채워져 나옵니다</td></tr></tbody></table><ul><li>해시는 서버가 만듭니다. 0~9와 a~f로 된 여덟 글자(hex)를 뽑고, 이미 있는 값이면 다시 뽑습니다. 파일 생성이 <code>O_EXCL</code>이라 같은 이름이 두 번 나올 일도 없고요. 사람이 해시를 타이핑할 자리는 이 화면 어디에도 없습니다.</li><li><code>deps</code>에 자유 입력이 없는 것이 그 칸의 요점입니다. 손으로 해시를 적던 시절에는 오타 한 글자가 존재하지 않는 선행이 됐습니다. 없는 티켓은 영원히 완료되지 않으니, 그것을 기다리는 티켓도 영원히 대기합니다. 고르기만 할 수 있으면 그런 사고가 구조적으로 생기지 않습니다.</li><li>발행에 성공하면 그 티켓 상세로 넘어갑니다. 그 이동이 다이얼로그를 닫습니다. 자기 티켓이 큐에 들어간 것을 그 자리에서 보게 됩니다.</li><li>쓰다 만 것이 있으면 닫기를 한 번 막습니다. <code>쓰던 내용이 있습니다</code>를 묻고, <code>버리고 닫기</code>를 고를 때만 지웁니다. 발행이 실패해도 다이얼로그는 열린 채 사유만 그 안에 뜹니다. 닫는 바람에 쓴 글을 날리는 일은 없습니다.</li></ul><h2 id="done-when을-쓰는-법" tabindex="-1"><code>## Done when</code>을 쓰는 법 <a class="header-anchor" href="#done-when을-쓰는-법" aria-label="Permalink to &quot;`## Done when`을 쓰는 법&quot;">​</a></h2><p>이 장에서 제일 중요한 자리입니다. <code>## Goal</code>이 왜 필요한지와 무엇을 만드는지를 2~4줄로 적는 칸이라면, <code>## Done when</code>은 끝났는지를 판정하는 문장입니다.</p><p>판정할 수 있다는 것은 곧 &quot;명령 X를 돌리면 Y가 나온다&quot;로 쓰였다는 뜻입니다.</p><p>나쁜 예:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Done when</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ ] CSV 내보내기가 잘 동작한다</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ ] 필터도 개선한다</span></span></code></pre></div><p>좋은 예:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Done when</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ ] </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`/orders`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">에 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`CSV 내보내기`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 버튼이 보인다</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ ] 누르면 지금 화면의 필터가 적용된 행만 담긴 파일이 떨어진다</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ ] 헤더 행의 컬럼명이 한글이다</span></span></code></pre></div><p>&quot;잘 동작한다&quot;는 세션이 자기 손으로 판정할 수 없는 문장입니다. 그러면 세션은 그 항목을 못 켜거나, 근거 없이 켭니다. 어느 쪽이든 화면이 거짓말을 하게 됩니다. 세션은 항목을 하나 만족시킬 때마다 그 자리에서 <code>- [ ]</code>를 <code>- [x]</code>로 바꾸고, 도는 티켓을 열어 어디까지 갔는지 보는 자리가 정확히 그 체크박스입니다(<a href="/docs/screens">화면 소개</a>의 진행 표시). 검증할 수 있는 문장이어야 그 표시가 사실이 됩니다.</p><p>&quot;필터도 개선한다&quot;는 다른 문제입니다. 한 티켓에 두 가지가 들어 있습니다. 항목이 여섯 개를 넘으면 쪼갤 신호로 보세요. 티켓 하나는 한 세션(5~25분)이 리뷰할 수 있는 변경 하나여야 합니다. 화면 3개와 그 테스트가 필요하다면 그건 티켓 하나가 아니라 넷입니다.</p><h2 id="kind-—-티켓의-분류-넷" tabindex="-1"><code>kind</code> — 티켓의 분류 넷 <a class="header-anchor" href="#kind-—-티켓의-분류-넷" aria-label="Permalink to &quot;`kind` — 티켓의 분류 넷&quot;">​</a></h2><p>값은 넷인데 셋만 select에 있습니다. 넷째는 앱이 씁니다.</p><p><strong><code>work</code></strong> — 지시입니다. 받은 페르소나가 수행하고, 끝나면 완료로 넘어갑니다. 직접 발행하는 티켓은 대부분 이것입니다.</p><p><strong><code>request</code></strong> — 부탁이나 질문입니다. 받은 사람은 답을 원본에 덧붙이지 않고 새 티켓으로 만듭니다. 원본은 질문의 기록으로 그대로 남습니다. <code>요구 접수</code>가 세우는 티켓이 이 값에 <code>persona: pm</code>이 붙은 것입니다.</p><p><strong><code>feedback</code></strong> — 결과보고나 지적입니다. 받은 사람은 조치가 필요하면 새 티켓을 만들고, 아니면 그냥 끝냅니다.</p><p><strong><code>answer</code></strong> — 답변 파일입니다. 선택지에는 없습니다. <code>답변 대기</code> 티켓에 사람이 답을 쓰면 앱이 이 값으로 파일을 하나 만드는데, 태어날 때부터 완료입니다. 아무도 그것을 수행하지 않기 때문입니다(다음 장 <a href="/docs/states">티켓이 지나는 상태</a> 참고).</p><p>엔진은 <code>kind</code> 값을 강제하지 않습니다. 그래도 보드의 kind 필터가 이 값으로 걸립니다. 다음에 이 티켓을 읽는 사람이나 세션이 지시인지 질문인지 보고인지를 알아볼 단서는 이 한 줄뿐입니다. 비워두지 마세요.</p><h2 id="persona-—-이-일을-맡는-역할" tabindex="-1"><code>persona</code> — 이 일을 맡는 역할 <a class="header-anchor" href="#persona-—-이-일을-맡는-역할" aria-label="Permalink to &quot;`persona` — 이 일을 맡는 역할&quot;">​</a></h2><p>고른 이름의 <code>personas/&lt;이름&gt;/PROFILE.md</code> 본문이 세션 프롬프트 머리에 그대로 인라인됩니다. 같은 일이라도 <code>developer</code>가 받으면 코드를 짜고 <code>qa</code>가 받으면 그 코드를 깨러 갑니다. 이 칸 하나가 그 차이를 만듭니다(<a href="/docs/personas">페르소나</a> 참고).</p><ul><li>페르소나는 워커가 아니라 티켓에 붙습니다. 아무 워커나 집어 가고, 집은 워커가 그 티켓의 <code>persona:</code>대로 세션을 엽니다.</li><li>select에는 프로필이 실제로 있는 이름만 뜹니다. 이름만 있고 <code>PROFILE.md</code>가 없으면 엔진이 경고만 남기고 그냥 돌지만, 그런 이름은 새 티켓의 선택지가 되지 않습니다.</li><li>비워도 됩니다. 워커가 열린 티켓 하나를 집어 세션을 여는 일을 디스패치라고 하는데, 페르소나가 비어 있어도 디스패치는 그대로 되고 그게 정상 경로입니다. 역할이 판단을 가르는 티켓에만 붙이세요.</li></ul><h2 id="deps-—-없으면-착수가-불가능한-것에만" tabindex="-1"><code>deps</code> — 없으면 착수가 불가능한 것에만 <a class="header-anchor" href="#deps-—-없으면-착수가-불가능한-것에만" aria-label="Permalink to &quot;`deps` — 없으면 착수가 불가능한 것에만&quot;">​</a></h2><p>멀티셀렉트에서 고른 티켓이 <strong>전부 완료</strong>여야 이 티켓이 큐에 뜹니다. 하나라도 안 끝났으면 보드 <code>대기</code> 레인에 주황색 <code>deps</code> 태그를 달고 앉아 있고, 그동안 어떤 워커도 집어가지 않습니다.</p><p>병렬로 돌 수 있는 일에는 걸지 마세요. 남발하면 워커가 놀고 큐가 직렬화됩니다. 워커가 여섯이어도 사슬로 엮인 티켓 여섯은 한 번에 하나씩 돕니다. 기준은 하나입니다. 그것이 안 끝나면 착수 자체가 불가능한가. &quot;먼저 끝나 있으면 참고하기 좋다&quot;는 <code>deps</code>가 아닙니다.</p><h2 id="복제-—-이미-있는-티켓에서-시작하기" tabindex="-1">복제 — 이미 있는 티켓에서 시작하기 <a class="header-anchor" href="#복제-—-이미-있는-티켓에서-시작하기" aria-label="Permalink to &quot;복제 — 이미 있는 티켓에서 시작하기&quot;">​</a></h2><p>티켓 상세 머리의 <code>복제</code>는 이 발행 다이얼로그를 <strong>원본 값으로 채워서 여는 버튼</strong>입니다. 새 화면이 아니라 같은 폼이라, 열린 자리에서 제목과 본문을 고쳐 발행하면 됩니다. 상태는 가리지 않습니다. 원본을 읽기만 하므로 진행중 티켓에서도 안전합니다.</p><p>넘어오는 값은 넷입니다. <code>title</code> · <code>kind</code> · <code>persona</code> · 본문 전문. 본문에는 워커가 붙인 <code>## 결과</code>·<code>## 블록</code>도 그대로 딸려 옵니다. 절 이름으로 잘라내는 규칙은 멀쩡한 절까지 먹기 때문이고, 지우는 자리가 눈앞의 textarea입니다.</p><p><strong><code>deps</code>는 비운 채로 열립니다.</strong> 미충족 선행을 그대로 복제하면 사본이 조용히 대기하게 됩니다. 선후는 그때의 큐 상태에 달린 값이라 멀티셀렉트에서 다시 고르세요. 엔진이 쓰는 키(<code>session_id</code>·<code>owner</code>·<code>pid</code>·<code>awaiting</code>…)도 넘어오지 않습니다. 새 티켓에 그 값이 들어가면 이미 할당된 것으로 보여 영원히 디스패치되지 않습니다.</p><h2 id="고칠-수-있는-티켓-못-고치는-티켓" tabindex="-1">고칠 수 있는 티켓, 못 고치는 티켓 <a class="header-anchor" href="#고칠-수-있는-티켓-못-고치는-티켓" aria-label="Permalink to &quot;고칠 수 있는 티켓, 못 고치는 티켓&quot;">​</a></h2><p>발행한 티켓의 본문·<code>kind</code>·<code>persona</code>·<code>deps</code>는 상세 화면에서 계속 고칠 수 있습니다. 상태에 따라 둘은 잠깁니다.</p><ul><li>완료 티켓은 읽기 전용입니다. 편집·삭제·할당 해제가 전부 막힙니다. <code>.done</code> 파일이 있다는 것 자체가 이 큐의 이력이라서 그렇습니다. 같은 일을 조건만 바꿔 다시 시키고 싶다면 그 자리가 위의 <code>복제</code>입니다.</li><li>진행중 티켓은 할당을 푼 뒤에야 고칩니다. 세션이 지금 그 파일을 쥐고 쓰는 중이라, 밑에서 고치면 도는 세션의 작업을 밟습니다. 잠금 카드의 <code>할당 해제</code>를 누르면 티켓이 큐로 되돌아오고, 그다음에 편집 폼이 열립니다.</li></ul><h2 id="나머지-frontmatter-키" tabindex="-1">나머지 frontmatter 키 <a class="header-anchor" href="#나머지-frontmatter-키" aria-label="Permalink to &quot;나머지 frontmatter 키&quot;">​</a></h2><p>다이얼로그가 묻는 다섯 칸이 <strong>사람이 쓰는 값의 전부</strong>입니다. 나머지 키는 디스패처와 엔진이 씁니다. 티켓 파일 맨 위 <code>---</code> 두 줄 사이에 <code>키: 값</code>으로 적히는 그 머리말을 frontmatter라고 부릅니다. 키 하나하나의 뜻과 누가 언제 쓰는지는 <a href="/docs/ref-frontmatter">frontmatter 필드</a>에 표로 정리해 두었습니다. 여기서 다시 세우지 않습니다.</p><p>다음은 <a href="/docs/states">티켓이 지나는 상태</a>입니다.</p>',40)])])}const g=t(s,[["render",i]]);export{k as __pageData,g as default};
